    // Dependencies are guaranteed to exist (checked at creation time, and cells are never removed).
    fn gather_values(&self, dependencies: &[CellId]) -> Vec<T> {
        dependencies
            .iter()
            .map(|dependency| self.value(*dependency).unwrap())
            .collect()
    }
